# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SINIF EŞYALARI VE OKULUN BÖLÜMLERİ (مُرَاجَعَةُ الْوَحْدَةِ الثَّانِيَةِ)</text>\n  <rect x="20" y="46" width="320" height="194" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Eril Sözcükler (هٰذَا - Bu)</text>\n  <text x="180" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Eşyalar: كِتَابٌ (Kitap) · قَلَمٌ (Kalem) · دَفْتَرٌ (Defter)</text>\n  <text x="180" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Mobilyalar: كُرْسِيٌّ (Sandalye) · مَقْعَدٌ / مَكْتَبٌ (Sıra)</text>\n  <text x="180" y="150" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Mekânlar: صَفٌّ (Sınıf) · مُخْتَبَرٌ (Laboratuvar) · مَقْصَفٌ (Kantin)</text>\n  <text x="180" y="176" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Kişiler: مُعَلِّمٌ (Erkek Öğretmen) · طَالِبٌ (Erkek Öğrenci)</text>\n  <text x="180" y="212" text-anchor="middle" font-size="11" fill="#334155">Soru: مَا هٰذَا؟ (Bu nedir?) / مَنْ هٰذَا؟ (Bu kimdir?)</text>\n\n  <rect x="360" y="46" width="320" height="194" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="520" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Dişil Sözcükler (هٰذِهِ - Bu)</text>\n  <text x="520" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#831843">• Eşyalar: سَبُّورَةٌ (Tahta) · حَقِيبَةٌ (Çanta) · مِمْحَاةٌ (Silgi)</text>\n  <text x="520" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#831843">• Eşyalar: طَاوِلَةٌ (Masa) · مِسْطَرَةٌ (Cetvel) · خَرِيطَةٌ (Harita)</text>\n  <text x="520" y="150" text-anchor="middle" font-size="12" font-weight="bold" fill="#831843">• Mekânlar: مَدْرَسَةٌ (Okul) · مَكْتَبَةٌ (Kütüphane) · حَدِيقَةٌ (Bahçe)</text>\n  <text x="520" y="176" text-anchor="middle" font-size="12" font-weight="bold" fill="#831843">• Kişiler: مُعَلِّمَةٌ (Kadın Öğretmen) · طَالِبَةٌ (Kız Öğrenci)</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11" fill="#334155">Soru: مَا هٰذِهِ؟ (Bu nedir?) / مَنْ هٰذِهِ؟ (Bu kimdir?)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DİYALOG KALIPLARI, HARF-İ CERLER VE YÖNERGELER</text>\n  <rect x="20" y="46" width="320" height="194" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="180" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Soru - Cevap ve Harf-i Cerler (فِي / إِلَى)</text>\n  <text x="180" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• هَلْ هٰذَا قَلَمٌ؟ — نَعَمْ، هٰذَا قَلَمٌ. (Evet, bu bir kalemdir.)</text>\n  <text x="180" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• هَلْ هٰذِهِ مِمْحَاةٌ؟ — لَا، هٰذِهِ حَقِيبَةٌ. (Hayır, bu çantadır.)</text>\n  <text x="180" y="152" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">• أَيْنَ الدَّفْتَرُ؟ — اَلدَّفْتَرُ فِي الْحَقِيبَةِ. (Çantanın içindedir.)</text>\n  <text x="180" y="178" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">• إِلَى أَيْنَ تَذْهَبُ؟ — أَذْهَبُ إِلَى الْمَكْتَبَةِ. (Kütüphaneye gidiyorum.)</text>\n  <text x="180" y="212" text-anchor="middle" font-size="11" fill="#334155">فِي (-de/-da) ve إِلَى (-e/-a) sonrası isim kesralı (-i) okunur.</text>\n\n  <rect x="360" y="46" width="320" height="194" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="520" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Sınıf Yönergeleri (Erkek / Kız Hitabı)</text>\n  <text x="520" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">• اِفْتَحْ / اِفْتَحِي (Aç!) — أَغْلِقْ / أَغْلِقِي (Kapat!)</text>\n  <text x="520" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">• خُذْ / خُذِي (Al!) — أَعْطِ / أَعْطِي (Ver!)</text>\n  <text x="520" y="150" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">• أَعْطِنِي / أَعْطِينِي الْقَلَمَ (Bana kalemi ver!)</text>\n  <text x="520" y="176" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">• اِجْلِسْ / اِجْلِسِي (Otur!) — قُمْ / قُومِي (Ayağa kalk!)</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11" fill="#475569">Kız öğrenciye yönelik emir fiillerin sonuna «ـِي» (î) eklenir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SESLETİM ÖZETİ VE VECİZ SÖZ: «اَلْعِلْمُ نَافِعٌ»</text>\n  <rect x="20" y="46" width="410" height="194" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="225" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Harekeler, Med, Cezim, Tenvin ve Şedde</text>\n  <text x="225" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Med (Uzatma): أُو - تِي - نَا (كِتَابٌ - صَدِيقِي - سَبُّورَةٌ)</text>\n  <text x="225" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Cezim (Sükûn): أَيْ - لَمْ - أَنْ (مَكْتَبٌ - دَفْتَرٌ - مَقْصَفٌ)</text>\n  <text x="225" y="150" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Tenvin (-un/-in/-an): أَبٌ - بَيْتًا - طَالِبَةٌ - قَلَمٍ</text>\n  <text x="225" y="176" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Şedde (Çift Okuma): مَدَّ - شَدَّ - كُلٌّ - صَفٌّ - كُرْسِيٌّ</text>\n  <text x="225" y="212" text-anchor="middle" font-size="11" fill="#475569">Harflerin kelime başında, ortasında ve sonunda yazılış biçimleri</text>\n\n  <rect x="450" y="46" width="230" height="194" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="565" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Bölümün Veciz Sözü</text>\n  <text x="565" y="118" text-anchor="middle" font-size="22" font-weight="bold" fill="#155e75">اَلْعِلْمُ نَافِعٌ</text>\n  <text x="565" y="150" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">«El-ilmü nâfi\'un»</text>\n  <text x="565" y="178" text-anchor="middle" font-size="13" font-weight="bold" fill="#164e63">Anlamı: İlim faydalıdır.</text>\n  <text x="565" y="212" text-anchor="middle" font-size="11" fill="#334155">Bilgi insanı doğruya ulaştırır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
